from jsonb_to_recordset($json$[{"id":"che-so-269","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For Al2(SO4)3, complete dissociation would give i of","options":["5","3","2","4"],"answer_index":0,"explanation":"2 Al³⁺ + 3 SO₄²⁻ = five ions per formula unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-270","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If i = 2 for a binary electrolyte AB, the degree of dissociation is","options":["1 (complete)","0.5","0","2"],"answer_index":0,"explanation":"i = 1 + (2 − 1)$\\alpha$ = 1 + $\\alpha$, so i = 2 means $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-271","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Observed $\\Delta T_f$ divided by the $\\Delta T_f$ calculated with the theoretical molar mass equals","options":["i","$K_b$","$K_f$","$\\pi$"],"answer_index":0,"explanation":"That ratio is the definition of the van’t Hoff factor from freezing-point data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-272","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"K4[Fe(CN)6] on complete ionisation yields particles numbering","options":["5","4","2","1"],"answer_index":0,"explanation":"Four K⁺ ions plus [Fe(CN)6]⁴⁻ give five particles, so i = 5 when fully split.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-273","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A binary electrolyte is 60% dissociated. The van’t Hoff factor is","options":["1.60","2.00","0.60","1.00"],"answer_index":0,"explanation":"i = 1 + (2 − 1)(0.60) = 1.60.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-274","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Acetic acid appears to have molar mass 120 g mol⁻¹ in benzene (true M = 60). Then i equals","options":["0.50","2.0","1.0","1.5"],"answer_index":0,"explanation":"i = $M_{\\mathrm{true}} / M_{\\mathrm{obs}} = 60/120 = 0.50$ (essentially complete dimerisation).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-275","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"BaCl2 is 80% dissociated. With n = 3, i is","options":["2.60","3.00","0.80","1.80"],"answer_index":0,"explanation":"i = 1 + (3 − 1)(0.80) = 2.60.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-276","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solute that should give $\\Delta T_b = 0.20$ K actually gives 0.30 K. The van’t Hoff factor is","options":["1.5","0.67","2.0","0.20"],"answer_index":0,"explanation":"i = 0.30 / 0.20 = 1.5.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-277","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Observed molar mass of NaCl in water is 30 g mol⁻¹ (formula mass 58.5). The factor i is nearest","options":["1.95","0.51","3.00","1.00"],"answer_index":0,"explanation":"i = 58.5 / 30 = 1.95, close to complete dissociation into two ions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-278","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For dimerisation with $\\alpha = 0.40$, i equals","options":["0.80","1.40","0.40","2.00"],"answer_index":0,"explanation":"i = 1 − $\\alpha$(1 − 1/n) = 1 − 0.40/2 = 0.80.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-279","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.10 m aqueous Ca(NO3)2 solution is 70% dissociated. Using $K_f = 1.86$ K kg mol⁻¹, the freezing-point depression is nearest","options":["0.45 K","0.19 K","0.56 K","1.86 K"],"answer_index":0,"explanation":"n = 3, i = 1 + 2 × 0.70 = 2.40; $\\Delta T_f = 2.40 \\times 1.86 \\times 0.10 = 0.446$ K ≈ 0.45 K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-280","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.050 M weak electrolyte is 40% dissociated into two ions. At 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹), osmotic pressure is nearest","options":["1.72 atm","1.23 atm","0.050 atm","2.46 atm"],"answer_index":0,"explanation":"i = 1.40; $\\pi = iCRT = 1.40 \\times 0.050 \\times 0.0821 \\times 300 \\approx 1.72$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
